"""Orchestrator: brief -> parallel evidence missions (one browser per website) -> rules -> submission.

Phases and deadlines follow docs/02-architecture.md. Every mission gets a progress checklist computed from the
blackboard, so the model always knows what is still missing and missions end as soon as their evidence is complete.
Every phase degrades gracefully: a failed mission leaves gaps that the rules handle; the submission phase always
runs, so the run ends with a signed bid whenever possible.
"""
import asyncio
import hashlib
import json
import os
import re
import time

from .. import llm
from ..browser.site import Site
from ..log import log
from ..rules import parse
from ..rules.resolve import Context, Result, build
from .explorer import Explorer, Mission
from .prompts import BRIEF_SYSTEM, EXTRACT_SYSTEM, KINDS
from .submit import submit_bid

# Qwen's reasoning combined with JSON output can run for minutes on long inputs; measured off by default.
THINKING_EXTRACT = os.environ.get("RFQ_THINKING_EXTRACT") == "1"
SUBMIT_RESERVE = float(os.environ.get("RFQ_SUBMIT_RESERVE", "480"))   # seconds kept for the submission phase
MATERIAL_REQUIRED = ["status_meaning", "bore_mm", "stroke_mm", "pressure_bar", "mounting", "unrestricted_stock",
                     "lead_time_stock_weeks", "lead_time_production_weeks", "pieces_per_carton"]


class Blackboard:
    """Append-only store of extractions: kind -> [{"data", "url", "t"}]."""

    def __init__(self):
        self.items: dict[str, list[dict]] = {}

    def add(self, kind: str, data: dict, url: str) -> None:
        self.items.setdefault(kind, []).append({"data": data, "url": url, "t": time.time()})

    def get(self, kind: str) -> list[dict]:
        return self.items.get(kind, [])

    def dump(self) -> dict:
        return {k: [{"url": i["url"], "data": i["data"]} for i in v] for k, v in self.items.items()}

    def load(self, dumped: dict) -> None:
        """Re-use the evidence of an earlier run (dev: iterate on rules/submission without re-exploring)."""
        for kind, items in dumped.items():
            for item in items:
                item = dict(item)
                url = item.pop("url", "")
                self.add(kind, item["data"] if set(item) == {"data"} else item, url)


class Orchestrator:
    def __init__(self, run: dict, sites: dict[str, Site]):
        self.run, self.sites = run, sites
        self.bb = Blackboard()
        self.end = run["expires_at"] / 1000
        self.brief: dict = {}
        self.result: Result | None = None
        self._cache: dict[str, str] = {}

    # ---------------------------------------------------------------- extraction helper (model-selected pages only)
    async def extract(self, kind: str, text: str, url: str) -> str:
        spec = KINDS.get(kind)
        if spec is None:
            return f"ERROR: unknown kind {kind}; use one of {list(KINDS)}"
        key = kind + hashlib.sha1(re.sub(r"\[(?:f\d+)?e\d+\]", "", text.split("\n", 1)[-1]).encode()).hexdigest()
        if key in self._cache:
            return "already extracted earlier: " + self._cache[key]
        prompt = (f"KIND: {kind} ({spec['describe']})\nReturn JSON with this shape:\n{spec['schema']}\n\n"
                  f"Task context: tender reference {self.brief.get('tender_reference')}, scenario date "
                  f"{self.brief.get('scenario_datetime_utc')}.\nPAGE URL: {url}\n<<<PAGE TEXT>>>\n{text[:60000]}\n<<<END>>>")
        data = await llm.ask_json(EXTRACT_SYSTEM, prompt, thinking=THINKING_EXTRACT, tag=f"extract:{kind}")
        if not data:
            return "extraction returned nothing"
        self.bb.add(kind, data, url)
        log("extracted", kind=kind, url=url[:160], data=data)
        self._cache[key] = summary = _summary(kind, data)
        return summary

    # ---------------------------------------------------------------- brief
    async def read_brief(self) -> None:
        brief = self.run["brief"]
        self.brief = await llm.ask_json(BRIEF_SYSTEM, brief, thinking=False, tag="brief")
        ref = parse.clean(self.brief.get("tender_reference"))
        if not ref or ref not in brief:   # the reference must be copied verbatim from the brief
            candidates = re.findall(r"\(([A-Z]{1,5}-[\w-]+)\)", brief)
            log("brief_reference_fallback", model=ref, candidates=candidates)
            if candidates:
                self.brief["tender_reference"] = candidates[0]
        log("brief", data=self.brief)

    def site_for(self, role: str) -> Site:
        site_id = (self.brief.get("sites") or {}).get(role)
        if site_id in self.sites:
            return self.sites[site_id]
        order = ["tender", "specification", "erp", "mail"]
        return list(self.sites.values())[order.index(role) % len(self.sites)]

    def mission(self, name: str, goal: str, kinds: list[str], steps: int, progress=None, context: str = "") -> Mission:
        return Mission(name=name, goal=goal, kinds={k: KINDS[k]["describe"] for k in kinds}, max_steps=steps,
                       deadline=self.end - SUBMIT_RESERVE, context=context, progress=progress)

    async def explore(self, site: Site, mission: Mission) -> Explorer | None:
        try:
            return await Explorer(site, mission, self.extract).run()
        except Exception as error:
            log("mission_crashed", mission=mission.name, error=f"{type(error).__name__}: {error}"[:500])
            return None

    # ---------------------------------------------------------------- progress checklists (from the blackboard)
    def positions(self) -> list[dict]:
        found: dict[str, dict] = {}
        for item in self.bb.get("positions"):
            for p in item["data"].get("positions") or []:
                if p.get("position"):
                    found[parse.clean(p["position"])] = p
        return list(found.values())

    def tender_progress(self) -> tuple[str, bool]:
        positions = self.positions()
        qa = self.bb.get("clarifications")
        entries = {parse.norm_id(e.get("number")) for i in qa for e in i["data"].get("entries") or [] if e.get("number")}
        collected = any("#collected" in i["url"] for i in qa)
        lines = [
            f"[{'x' if positions else ' '}] positions: " + (", ".join(f"{p['position']} {p.get('quantity')} {p.get('unit')} "
                                                                       f"-> {p.get('requirement_ref')}" for p in positions) or "not found yet"),
            f"[{'x' if entries else ' '}] Q&A entries: {len(entries)}" + ("" if collected or not entries else
                                                                          " (only one page extracted: make sure ALL pages were read)"),
        ]
        return "\n".join(lines), bool(positions and entries and collected)

    def current_revision(self) -> str | None:
        current = None
        for item in self.bb.get("spec_revisions"):
            for r in item["data"].get("revisions") or []:
                status = parse.clean(r.get("status_text")).lower()
                if r.get("is_current") is True or any(w in status for w in ("gültig", "aktuell", "current")):
                    current = parse.norm_id(r.get("revision"))
        return current

    def requirements(self) -> dict[str, dict]:
        current, found = self.current_revision(), {}
        for item in self.bb.get("requirements"):
            rev = parse.norm_id(item["data"].get("revision"))
            if current and rev and rev != current:
                continue
            for r in item["data"].get("requirements") or []:
                if r.get("ref"):
                    found[parse.norm_id(r["ref"])] = {**r, "revision": rev}
        return found

    def spec_progress(self) -> tuple[str, bool]:
        current, reqs = self.current_revision(), self.requirements()
        needed = {parse.norm_id(p.get("requirement_ref")) for p in self.positions() if p.get("requirement_ref")}
        missing = sorted(needed - set(reqs))
        lines = [f"[{'x' if current else ' '}] revision marked current: {current or 'unknown (extract the revision list with statuses)'}",
                 f"[{'x' if reqs else ' '}] requirements of the current revision: {sorted(reqs) or 'none yet'}"]
        if needed:
            lines.append(f"[{'x' if not missing else ' '}] requirements referenced by the tender positions: "
                         f"{sorted(needed)}" + (f" — missing {missing}" if missing else ""))
        complete = bool(current and reqs and (not missing if needed else any("#collected" in i["url"] for i in self.bb.get("requirements"))))
        return "\n".join(lines), complete

    def materials(self) -> dict[str, dict]:
        merged: dict[str, dict] = {}
        for item in self.bb.get("materials"):
            for m in item["data"].get("materials") or []:
                num = parse.norm_id(m.get("material_number"))
                if not num:
                    continue
                target = merged.setdefault(num, {"material_number": m["material_number"], "conditions": [], "records": None})
                for k, v in m.items():
                    if k == "conditions":
                        target["conditions"] += [c for c in v or [] if c.get("scales")]
                    elif k == "condition_records_total" and v:
                        target["records"] = parse.integer(v)
                    elif v not in (None, "", []):
                        target[k] = v
        return merged

    def erp_progress(self, group: str, reqs: list[dict] | None = None) -> tuple[str, bool]:
        mats = [m for m in self.materials().values() if parse.norm_id(m.get("catalog_group")) == parse.norm_id(group)]
        if not mats:
            return f"[ ] no materials of group {group} found yet (search for the group key)", False
        lines, complete = [], True
        for m in mats:
            mismatch = _mismatch(m, reqs or [])
            if mismatch:
                lines.append(f"[x] {m['material_number']}: does not fit the requirement ({mismatch}); no more data needed")
                continue
            missing = [f for f in MATERIAL_REQUIRED if m.get(f) in (None, "", [])]
            if m.get("status_meaning") != "blocked":
                records = len({json.dumps(c.get("valid_from")) + json.dumps(c.get("currency")) for c in m["conditions"]})
                if not records:
                    missing.append("price condition records WITH quantity scales (open the scales view via its link)")
                elif m.get("records") and records < m["records"]:
                    missing.append(f"scales of all {m['records']} condition records (have {records})")
            else:
                missing = [f for f in missing if f in ("bore_mm", "stroke_mm", "pressure_bar", "mounting")]
            complete &= not missing
            lines.append(f"[{'x' if not missing else ' '}] {m['material_number']} ({m.get('status_meaning') or 'status ?'})"
                         + (f": missing {', '.join(missing)}" if missing else ": complete"))
        return "\n".join(lines), complete

    def mail_progress(self) -> tuple[str, bool]:
        ref = parse.norm_id(self.brief.get("tender_reference"))
        pages: dict[str, set[int]] = {}
        totals: dict[str, int] = {}
        listed = {}
        for item in self.bb.get("mail_list"):
            folder = parse.clean(item["data"].get("folder")).lower() or "?"
            pages.setdefault(folder, set()).add(parse.integer(item["data"].get("page")) or 1)
            if parse.integer(item["data"].get("pages_total")):
                totals[folder] = parse.integer(item["data"].get("pages_total"))
            for m in item["data"].get("messages") or []:
                subject = parse.norm_id(m.get("subject"))
                if ref and ref in subject and "TAN" not in subject and m.get("url"):
                    listed[_url_key(m["url"])] = parse.clean(m.get("subject"))
        done = {_url_key(i["url"]) for i in self.bb.get("mail_message")}
        topics = sorted({i["data"].get("topic") for i in self.bb.get("mail_message") if i["data"].get("topic")})
        missing = [f"{subject} -> {url}" for url, subject in listed.items() if url not in done]
        unread_pages = {f: sorted(set(range(1, totals[f] + 1)) - pages[f]) for f in totals if set(range(1, totals[f] + 1)) - pages[f]}
        lines = [f"folders listed: " + (", ".join(f"{f} pages {sorted(p)}" + (f" of {totals[f]}" if f in totals else "")
                                                 for f, p in pages.items()) or "none") + " (check inbox AND archive/other folders)",
                 f"messages opened: {len(done)}; topics found: {topics}"]
        if unread_pages:
            lines.append(f"list pages not read yet: {unread_pages} (read_all_pages on the list, then extract mail_list)")
        if missing:
            lines.append("listed but not opened yet (use extract_urls with kind mail_message):\n  " + "\n  ".join(missing[:30]))
        return "\n".join(lines), len(pages) >= 2 and bool(listed) and not missing and not unread_pages

    # ---------------------------------------------------------------- evidence phase
    async def gather_evidence(self) -> None:
        ref = self.brief.get("tender_reference")
        records = self.brief.get("authorized_records") or []
        topics = "\n".join(f"- {r.get('topic')}: subject keyword '{r.get('subject_keyword')}', sender "
                           f"'{r.get('sender_localpart')}@<bidder domain>'" for r in records)
        tender = self.mission("tender", f"""Find the tender with the exact reference {ref} and collect:
1. If documents or the bid area need a registration of interest (e.g. "Teilnahme bekunden" / expression of
   interest), register it. Optionally extract kind 'tender_overview'.
2. The bill of quantities / position list with the ORIGINAL quantities, units and requirement references
   (kind 'positions'). Documents may be in iframes, viewers, ZIP bundles or menus; prefer extract_urls on the
   document links (one link per document).
3. ALL bidder questions & answers (Q&A / Bieterfragen) of every page: use read_all_pages on the list's 'next page'
   link (it may sit inside a frame, ref like f2e7), then extract kind 'clarifications' with source='collected'.
Do not start the bid submission, do not ask questions.""", ["tender_overview", "positions", "clarifications"], 30,
            progress=self.tender_progress)
        spec = self.mission("specification", f"""Find the buyer's technical specification (Lastenheft / technical
specification / data sheet) for tender {ref} and collect the requirements of the revision MARKED CURRENT
(status such as "gültig"/"aktuell"; the viewer may open an old revision first; dates may use mixed formats).
1. Pass any document-release form honestly: choose the binding/reference option (not archive copy, not preview),
   copy the receipt number shown, tick the required acknowledgement, request read access.
2. Extract the revision list with statuses (kind 'spec_revisions'); statuses may be tooltips ([info: …]).
3. Open the CURRENT revision and read ALL requirement pages (read_all_pages on its 'next page' link), then extract
   kind 'requirements' with source='collected'.""", ["spec_revisions", "requirements"], 30, progress=self.spec_progress)
        mail = self.mission("mail", f"""In the sales mailbox, collect every message about tender {ref} that is one of:
- the sales director's discount approval (sender '{self.brief.get('director_localpart')}@<bidder domain>')
{topics}
Mail search combines words with AND. Strategy: search the exact reference alone; read all result pages
(read_all_pages on the 'next page' link) and extract kind 'mail_list' with source='collected'; then extract_urls with
kind 'mail_message' for EVERY listed message whose subject contains the reference (skip signing-TAN messages;
look-alike references are fine to open, they are filtered later). Then switch to the archive folder (and any other
folder) and do the same. If a search says there are too many results, add the subject keyword.""",
            ["mail_list", "mail_message"], 40, progress=self.mail_progress)
        results = await asyncio.gather(self.explore(self.site_for("tender"), tender),
                                       self.explore(self.site_for("specification"), spec),
                                       self.explore(self.site_for("mail"), mail), self.erp_phase())
        flat = [r for r in results if not isinstance(r, list)] + [x for r in results if isinstance(r, list) for x in r]
        log("evidence_done", missions=[(r.mission.name, r.summary[:200], r.missing) if r else None for r in flat],
            kinds={k: len(v) for k, v in self.bb.items.items()})

    async def erp_phase(self) -> list:
        """One ERP mission per catalogue group, in parallel tabs of the ERP browser (shared session)."""
        while not self.spec_progress()[1] and time.time() < self.end - SUBMIT_RESERVE - 240:
            await asyncio.sleep(2)
        reqs = self.requirements()
        needed = {parse.norm_id(p.get("requirement_ref")) for p in self.positions() if p.get("requirement_ref")}
        if needed & set(reqs):
            reqs = {k: v for k, v in reqs.items() if k in needed}   # only what the tender asks for
        groups: dict[str, list[dict]] = {}
        for r in reqs.values():
            groups.setdefault(parse.clean(r.get("catalog_group")) or "?", []).append(r)
        log("erp_groups", groups={g: [r.get("ref") for r in rs] for g, rs in groups.items()})
        base = self.site_for("erp")
        missions = []
        for index, (group, rs) in enumerate(groups.items()):
            described = "; ".join(f"requirement {r.get('ref')}: bore {r.get('bore_mm')}, stroke {r.get('stroke_mm')}"
                                  f"{' (usable stroke; the nominal ERP stroke is longer)' if r.get('usable_stroke') else ''}, "
                                  f"pressure {r.get('pressure_bar')}, mounting {r.get('mounting')}, certification "
                                  f"{r.get('certification') or 'none'}" for r in rs)
            mission = self.mission(f"erp:{group}", f"""Collect ERP data for catalogue group {group} ({described}).
1. Search the materials with the group key (material search / search help; at most ~20 hits are shown, empty or too
   broad searches show nothing) and extract kind 'materials' from the result list.
2. For EVERY material of the group (look-alikes differ in one attribute or in status) open its detail views and
   extract kind 'materials' from each: technical data, status (+ its legend) and lead times, stock down to the
   storage-location level (freely usable stock), and ALL price condition records with their quantity scales (scales
   may be on a separate tab/view; several records may be paged). Prefer extract_urls with several detail URLs.
The progress checklist tells you what is still missing per material.""", ["materials"], 35,
                                   progress=lambda g=group, rs=rs: self.erp_progress(g, rs))
            site = base if index == 0 else await base.spawn()
            missions.append(self.explore(site, mission))
        return list(await asyncio.gather(*missions))

    # ---------------------------------------------------------------- rules + submission
    def resolve(self) -> Result:
        brief = self.brief
        authorized = {r.get("topic"): r.get("sender_localpart") for r in brief.get("authorized_records") or []
                      if r.get("topic") and r.get("sender_localpart")}
        ctx = Context(tender_reference=parse.clean(brief.get("tender_reference")),
                      scenario=parse.when(brief.get("scenario_datetime_utc")) or parse.when("2000-01-01T00:00:00Z"),
                      director_localpart=brief.get("director_localpart"), authorized=authorized)
        result = build(ctx, self.bb.items)
        for line in result.trace:
            log("trace", line=line)
        log("answer", answer=result.answer, skipped=result.skipped)
        return result

    async def run_all(self, replay: dict | None = None) -> Result | None:
        result = None
        try:
            if replay:
                self.brief = replay["brief"]
                self.bb.load(replay["evidence"])
                log("replay", kinds={k: len(v) for k, v in self.bb.items.items()})
            else:
                await self.read_brief()
                await asyncio.wait_for(self.gather_evidence(), timeout=max(60, self.end - SUBMIT_RESERVE - time.time()))
        except Exception as error:   # never stop before submitting
            log("evidence_phase_error", error=f"{type(error).__name__}: {error}"[:500])
        try:
            result = self.resolve()
        except Exception as error:
            log("resolve_error", error=f"{type(error).__name__}: {error}"[:500])
        if result is None:
            result = Result({"tender_reference": self.brief.get("tender_reference", ""), "decision": "bid",
                             "currency": "EUR", "discount_percent": 0, "positions": [], "total_net": 0}, [], [], {})
        self.result = result
        try:
            await submit_bid(self, result)
        except Exception as error:
            log("submit_error", error=f"{type(error).__name__}: {error}"[:500])
        log("usage", **llm.usage)
        return result


def _mismatch(m: dict, reqs: list[dict]) -> str:
    """Why a material cannot fit any of the requirements (empty if it may fit or data is missing).
    Usable-stroke requirements are not compared on stroke (the nominal stroke is longer)."""
    if not reqs:
        return ""
    reasons = []
    for r in reqs:
        why = []
        for f in ("bore_mm", "pressure_bar") + (() if r.get("usable_stroke") else ("stroke_mm",)):
            a, b = parse.number(m.get(f)), parse.number(r.get(f))
            if a is not None and b is not None and a != b:
                why.append(f"{f} {a}≠{b}")
        if m.get("mounting") and r.get("mounting") and not parse.same_text(m["mounting"], r["mounting"]):
            why.append(f"mounting {m['mounting']}≠{r['mounting']}")
        if m.get("certification") is not None and parse.cert(m.get("certification")) != parse.cert(r.get("certification")):
            why.append(f"certification {m.get('certification')}≠{r.get('certification') or 'none'}")
        if not why:
            return ""
        reasons.append(", ".join(why))
    return "; ".join(reasons)


def _url_key(url: str) -> str:
    import html
    from urllib.parse import urlparse
    parsed = urlparse(html.unescape(str(url)).split("#")[0])
    return (parsed.path + "?" + parsed.query).rstrip("?")


def _summary(kind: str, data: dict) -> str:
    """A complete but compact confirmation of what was extracted, for the navigating model."""
    if kind == "positions":
        return f"{len(data.get('positions') or [])} positions: " + ", ".join(
            f"{p.get('position')} {p.get('quantity')} {p.get('unit')}" for p in data.get("positions") or [])
    if kind == "clarifications":
        return f"{len(data.get('entries') or [])} Q&A entries: " + ", ".join(str(e.get("number")) for e in data.get("entries") or [])
    if kind == "requirements":
        return f"revision {data.get('revision')}: " + ", ".join(
            f"{r.get('ref')} (group {r.get('catalog_group')})" for r in data.get("requirements") or [])
    if kind == "spec_revisions":
        return "revisions: " + ", ".join(f"{r.get('revision')} {r.get('status_text')}" for r in data.get("revisions") or [])
    if kind == "materials":
        return "; ".join(f"{m.get('material_number')}: " + ", ".join(
            k for k, v in m.items() if v not in (None, "", []) and k not in ("material_number", "description"))
            for m in data.get("materials") or []) or "no materials on this page"
    if kind == "mail_list":
        return f"folder {data.get('folder')}, mailbox {data.get('mailbox_address')}:\n" + "\n".join(
            f"  {m.get('subject')} | {m.get('sender')} | {m.get('datetime_utc')} | {m.get('url')}" for m in data.get("messages") or [])
    if kind == "mail_message":
        return f"'{data.get('subject')}' from {data.get('sender')} ({data.get('topic')})"
    return json.dumps(data, ensure_ascii=False)[:500]

"""From extracted evidence to the bid: deterministic application of the brief's rules (docs/04-business-rules.md).

Input is the blackboard (raw extractions with source URLs) and the task context. Output is the answer (schema of the
run) plus a trace of every decision and the positions that could not be completed (to be skipped in the form).
Nothing here raises on missing data: it degrades to the best possible answer and says why in the trace.
"""
from collections import defaultdict
from dataclasses import dataclass, field
from datetime import datetime
from decimal import ROUND_FLOOR, ROUND_HALF_UP, Decimal as D
from math import ceil

from .parse import cert, clean, day, integer, norm_id, number, same_text, when

CENT = D("0.01")


def r2(value: D) -> D:
    return value.quantize(CENT, ROUND_HALF_UP)


@dataclass
class Context:
    tender_reference: str
    scenario: datetime
    director_localpart: str | None = None
    authorized: dict[str, str] = field(default_factory=dict)      # topic -> sender local part
    mailbox_domain: str | None = None


@dataclass
class Result:
    answer: dict
    trace: list[str]
    skipped: list[str]                # positions we could not complete
    breakdown: dict                   # per position, unrounded components (for logs)


def largest_remainder(total: D, weights: dict[str, D]) -> dict[str, D]:
    """Distribute `total` in cents proportionally; floor first, remaining cents to the largest remainders,
    ties by ascending position id."""
    weights = {k: w for k, w in weights.items() if w > 0}
    if not weights or total <= 0:
        return {k: D(0) for k in weights}
    cents = int((total * 100).to_integral_value(ROUND_HALF_UP))
    wsum = sum(weights.values())
    raw = {k: D(cents) * w / wsum for k, w in weights.items()}
    base = {k: int(v.to_integral_value(ROUND_FLOOR)) for k, v in raw.items()}
    for k in sorted(weights, key=lambda k: (-(raw[k] - base[k]), k))[: cents - sum(base.values())]:
        base[k] += 1
    return {k: D(c) / 100 for k, c in base.items()}


def marginal_bonus(total: D, bands: list[dict]) -> D:
    credit = D(0)
    for band in bands:
        low = number(band.get("from_eur")) or D(0)
        high = number(band.get("to_eur"))
        rate = (number(band.get("rate_percent")) or D(0)) / 100
        top = total if high is None else min(total, high)
        if top > low:
            credit += (top - low) * rate
    return r2(credit)


def build(ctx: Context, bb: dict[str, list[dict]]) -> Result:
    trace: list[str] = []
    note = trace.append
    T = ctx.scenario
    ref_id = norm_id(ctx.tender_reference)

    # ---------------------------------------------------------------- positions & quantities
    positions: dict[str, dict] = {}
    for item in bb.get("positions", []):
        for p in item["data"].get("positions") or []:
            pid = clean(p.get("position"))
            if pid:
                positions.setdefault(pid, {}).update({k: v for k, v in p.items() if v not in (None, "")})
    note(f"positions: {list(positions)}")

    entries: dict[str, dict] = {}
    for item in bb.get("clarifications", []):
        for e in item["data"].get("entries") or []:
            if e.get("number"):
                entries[norm_id(e["number"])] = e
    withdrawn = {norm_id(f.get("withdrawn_number")) for e in entries.values() for f in e.get("facts") or []
                 if f.get("type") == "withdrawal" and f.get("withdrawn_number")}
    if withdrawn:
        note(f"withdrawn Q&A answers: {sorted(withdrawn)}")
    facts = []                                                   # (datetime, number, fact)
    for key, e in entries.items():
        at = when(e.get("datetime_utc"))
        if key in withdrawn:
            continue
        if at is not None and at > T:
            note(f"Q&A {key} is dated after the scenario date; ignored")
            continue
        for f in e.get("facts") or []:
            facts.append((at or datetime.min.replace(tzinfo=T.tzinfo), integer(key) or 0, f))
    facts.sort(key=lambda x: (x[0], x[1]))

    def latest(kind: str, pid: str | None = None, pred=lambda f: True) -> dict | None:
        found = None
        for _, _, f in facts:
            if f.get("type") == kind and (pid is None or same_text(f.get("position"), pid)) and pred(f):
                found = f
        return found

    # ---------------------------------------------------------------- specification
    revisions = [r for item in bb.get("spec_revisions", []) for r in item["data"].get("revisions") or []]
    current = [r for r in revisions if r.get("is_current") is True] or \
              [r for r in revisions if any(w in clean(r.get("status_text")).lower() for w in ("gültig", "aktuell", "current", "valid"))]
    current_rev = norm_id(current[-1]["revision"]) if current else None
    note(f"current specification revision: {current_rev}")
    requirements: dict[str, dict] = {}
    for item in bb.get("requirements", []):
        rev = norm_id(item["data"].get("revision"))
        if current_rev and rev and rev != current_rev:
            note(f"ignoring requirements of revision {rev} (not current)")
            continue
        for r in item["data"].get("requirements") or []:
            if r.get("ref"):
                requirements[norm_id(r["ref"])] = {**r, "revision": rev or current_rev}

    # ---------------------------------------------------------------- mails (authority and time)
    domain = ctx.mailbox_domain
    for item in bb.get("mail_list", []):
        address = clean(item["data"].get("mailbox_address"))
        if "@" in address:
            domain = address.split("@", 1)[1].lower()
    mails = []
    for item in bb.get("mail_message", []):
        m = item["data"]
        at = when(m.get("datetime_utc"))
        if m.get("is_draft_or_preview"):
            continue
        if norm_id(m.get("reference")) != ref_id:
            continue
        if at is None or at > T:
            note(f"mail '{clean(m.get('subject'))}' dated {at} is after the scenario date or undated; ignored")
            continue
        mails.append((at, m))
    mails.sort(key=lambda x: x[0])

    def authorized(topic: str, sender: str) -> bool:
        local = (ctx.director_localpart if topic == "discount" else ctx.authorized.get(topic)) or ""
        sender = clean(sender).lower()
        if "<" in sender:
            sender = sender.split("<")[-1].rstrip(">")
        if local and not sender.startswith(local.lower() + "@"):
            return False
        if domain and not sender.endswith("@" + domain):
            return False
        return True

    def topic_records(topic: str) -> list[dict]:
        return [m for _, m in mails if m.get("topic") == topic and authorized(topic, m.get("sender", ""))]

    def keyed(topic: str, field_name: str) -> dict[str, dict]:
        out: dict[str, dict] = {}
        for m in topic_records(topic):                    # ascending by date: newer records replace older ones
            for k, v in ((m.get("data") or {}).get(field_name) or {}).items():
                out[norm_id(k)] = v
        return out

    clauses = keyed("clause_rules", "groups")
    reserves = keyed("tech_release", "entries")
    tariffs = keyed("packaging", "tariffs")
    commitments = keyed("delivery", "commitments")
    fx_rates = keyed("fx", "rates")
    pools = keyed("setup_pool", "pools")
    bonus_plans = keyed("project_bonus", "plans")
    indices = keyed("metal_index", "indices")
    note(f"mail keys: clauses={list(clauses)} reserves={list(reserves)} tariffs={list(tariffs)} "
         f"commitments={list(commitments)} fx={list(fx_rates)} pools={list(pools)} bonus={list(bonus_plans)} "
         f"indices={list(indices)} domain={domain}")

    # ---------------------------------------------------------------- materials
    materials: dict[str, dict] = {}
    for item in bb.get("materials", []):
        for m in item["data"].get("materials") or []:
            num = norm_id(m.get("material_number"))
            if not num:
                continue
            target = materials.setdefault(num, {"material_number": clean(m["material_number"]), "conditions": []})
            for k, v in m.items():
                if k == "conditions":
                    for c in v or []:
                        if c.get("scales") and c not in target["conditions"]:
                            target["conditions"].append(c)
                elif v not in (None, "", []):
                    target[k] = v

    def matches(mat: dict, req: dict, stroke: D | None) -> bool:
        """Exact match. stroke=None means 'nominal stroke unknown' (e.g. end reserve not found): stroke is then not
        compared here and the caller picks among the remaining candidates."""
        checks = [(number(mat.get("bore_mm")), number(req.get("bore_mm"))),
                  (number(mat.get("pressure_bar")), number(req.get("pressure_bar")))]
        if stroke is not None:
            checks.append((number(mat.get("stroke_mm")), stroke))
        if any(a is None or b is None or a != b for a, b in checks):
            return False
        if not same_text(mat.get("mounting"), req.get("mounting")):
            return False
        return cert(mat.get("certification")) == cert(req.get("certification"))

    # ---------------------------------------------------------------- per position
    resolved: dict[str, dict] = {}
    skipped: list[str] = []
    no_material: list[str] = []
    for pid, p in positions.items():
        qty, unit = number(p.get("quantity")), clean(p.get("unit"))
        change = latest("quantity_change", pid)
        if change:
            qty, unit = number(change.get("quantity")), clean(change.get("unit")) or unit
            note(f"{pid}: quantity from Q&A -> {qty} {unit}")
        req = requirements.get(norm_id(p.get("requirement_ref")))
        if req is None:
            note(f"{pid}: requirement {p.get('requirement_ref')} not found")
            skipped.append(pid)
            continue
        if unit and not unit.lower().startswith(("st", "stk", "stück", "pc", "piece")):
            per_set = integer(req.get("pieces_per_set"))
            if per_set:
                qty = qty * per_set
                note(f"{pid}: {unit} -> pieces x{per_set} = {qty}")
            else:
                note(f"{pid}: unit {unit} without pieces-per-set conversion")
        q = int(qty) if qty is not None else 0
        attrs = dict(req)
        for attribute in ("bore", "stroke", "pressure", "mounting", "certification"):
            amendment = latest("tech_amendment", None, lambda f, a=attribute: norm_id(f.get("revision")) == norm_id(req["revision"])
                               and norm_id(f.get("requirement")) == norm_id(req["ref"]) and f.get("attribute") == a)
            if amendment:
                field_name = {"bore": "bore_mm", "stroke": "stroke_mm", "pressure": "pressure_bar"}.get(attribute, attribute)
                attrs[field_name] = amendment.get("value")
                note(f"{pid}: amendment {attribute} = {amendment.get('value')}")
        stroke = number(attrs.get("stroke_mm"))
        usable_floor = None
        if attrs.get("usable_stroke") and stroke is not None:
            key = norm_id(attrs.get("end_reserve_key"))
            entry = reserves.get(key)
            if entry and (not entry.get("revision") or norm_id(entry["revision"]) == norm_id(req["revision"])):
                reserve = number(entry.get("reserve_mm_per_end")) or D(0)
                stroke = stroke + 2 * reserve
                note(f"{pid}: usable stroke + 2x{reserve} ({key}) = nominal {stroke}")
            else:
                note(f"{pid}: WARNING end reserve {key} for revision {req['revision']} not found; nominal stroke unknown")
                usable_floor, stroke = stroke, None
        group = norm_id(attrs.get("catalog_group"))
        candidates = [m for m in materials.values() if not group or not m.get("catalog_group") or norm_id(m.get("catalog_group")) == group]
        fitting = [m for m in candidates if matches(m, attrs, stroke)]
        if stroke is None and usable_floor is not None:
            # unknown reserve: the nominal stroke must exceed the usable one; prefer the closest such material
            longer = [m for m in fitting if (number(m.get("stroke_mm")) or D(0)) > usable_floor]
            ranked = sorted(longer or fitting, key=lambda m: (m.get("status_meaning") != "active", number(m.get("stroke_mm")) or D(0)))
            fitting = ranked[:1]
            uncertain = True
        else:
            uncertain = False
        active = [m for m in fitting if m.get("status_meaning") == "active"]
        note(f"{pid}: group {group} candidates={[m['material_number'] for m in candidates]} "
             f"fitting={[m['material_number'] for m in fitting]} active={[m['material_number'] for m in active]}")
        if not active:
            if fitting and all(m.get("status_meaning") is None for m in fitting):
                active = fitting
                note(f"{pid}: status unknown, using fitting material")
            elif candidates and not uncertain:
                no_material.append(pid)
                continue
            else:
                skipped.append(pid)
                continue
        material = sorted(active, key=lambda m: (not m.get("conditions"), m["material_number"]))[0]
        resolved[pid] = {"q": q, "material": material, "req": attrs}

    # A position without any active matching material (and evidence that we looked) means no bid.
    if no_material:
        note(f"no active matching material for {no_material}: no_bid")
        answer = {"tender_reference": ctx.tender_reference, "decision": "no_bid", "currency": "EUR",
                  "discount_percent": 0, "positions": [], "total_net": 0}
        return Result(answer, trace, [], {})

    # ---------------------------------------------------------------- prices
    def condition_price(m: dict, q: int, pid: str) -> D | None:
        valid = []
        for c in m.get("conditions") or []:
            start, end = when(c.get("valid_from")), when(c.get("valid_to"))
            if start and start > T and day(c.get("valid_from")) != T.date():
                continue
            if end and end < T and day(c.get("valid_to")) != T.date():
                continue
            valid.append(c)
        if not valid:
            note(f"{pid}: no price condition valid on {T.date()}")
            return None
        c = valid[-1]
        fmt = c.get("number_format")
        scales = sorted(((number(s.get("from_qty"), fmt), number(s.get("price"), fmt)) for s in c.get("scales") or []),
                        key=lambda s: s[0] or 0)
        usable = [s for s in scales if s[0] is not None and s[1] is not None and s[0] <= q] or scales[:1]
        if not usable:
            return None
        price = usable[-1][1] / (number(c.get("price_unit_qty"), fmt) or D(1))
        currency = clean(c.get("currency")).upper() or "EUR"
        if currency != "EUR":
            rate = fx_rates.get(norm_id(c.get("fx_key")))
            eur = number((rate or {}).get("eur_per_unit"))
            if eur is None:
                note(f"{pid}: no FX rate for {c.get('fx_key')} ({currency}); price left in {currency}")
                eur = D(1)
            price *= eur
        base = r2(price)
        note(f"{pid}: scale from {usable[-1][0]} price {usable[-1][1]} / unit {c.get('price_unit_qty')} {currency} -> base {base} EUR")
        return base

    for pid, r in resolved.items():
        r["base"] = condition_price(r["material"], r["q"], pid)

    # discount (order level, possibly conditional)
    approvals = [m for m in topic_records("discount") if (m.get("data") or {}).get("is_approval")]
    discount = D(0)
    if approvals:
        data = approvals[-1]["data"]
        discount = number(data.get("percent")) or D(0)
        threshold = number(data.get("min_order_value_eur"))
        if threshold is not None:
            order_value = r2(sum((r["q"] * r["base"] for r in resolved.values() if r["base"] is not None), D(0)))
            if order_value < threshold:
                note(f"discount condition failed: {order_value} < {threshold}")
                discount = D(0)
            else:
                note(f"discount condition met: {order_value} >= {threshold}")
        note(f"discount {discount} % from '{clean(approvals[-1].get('subject'))}'")
    else:
        note("no discount approval found: 0 %")
    d = discount / 100

    # setup pools and project bonus
    pool_members: dict[str, list[str]] = defaultdict(list)
    bonus_members: dict[str, list[str]] = defaultdict(list)
    assignments = {}
    for pid in resolved:
        a: dict = {}
        for _, _, f in facts:      # merge assignment facts in date order; later non-empty keys win
            if f.get("type") == "assignment" and same_text(f.get("position"), pid):
                a.update({k: v for k, v in f.items() if v not in (None, "")})
        assignments[pid] = a
        if a.get("setup_pool_key"):
            pool_members[norm_id(a["setup_pool_key"])].append(pid)
        if a.get("bonus_plan_key"):
            bonus_members[norm_id(a["bonus_plan_key"])].append(pid)
    pool_share: dict[str, D] = defaultdict(D)
    for key, members in pool_members.items():
        amount = number((pools.get(key) or {}).get("amount_eur"))
        if amount is None:
            note(f"setup pool {key}: amount not found")
            continue
        weights = {p: D(resolved[p]["q"]) * (number(resolved[p]["material"].get("allocation_weight_g")) or D(0)) for p in members}
        for p, share in largest_remainder(amount, weights).items():
            pool_share[p] += share
        note(f"setup pool {key} {amount} -> {dict(pool_share)}")
    bonus_share: dict[str, D] = defaultdict(D)
    for key, members in bonus_members.items():
        plan = bonus_plans.get(key)
        eligible = {p: resolved[p]["q"] * resolved[p]["base"] for p in members if resolved[p]["base"] is not None}
        if not plan or not eligible:
            note(f"bonus plan {key}: not found or no eligible prices")
            continue
        credit = marginal_bonus(sum(eligible.values()), plan.get("bands") or [])
        for p, share in largest_remainder(credit, eligible).items():
            bonus_share[p] += share
        note(f"bonus plan {key}: base {sum(eligible.values())} credit {credit}")

    pooled: dict[str, int] = defaultdict(int)
    for r in resolved.values():
        pooled[norm_id(r["material"]["material_number"])] += r["q"]

    out_positions, breakdown, total = [], {}, D(0)
    for pid, r in resolved.items():
        m, q, base = r["material"], r["q"], r["base"]
        if base is None or q <= 0:
            skipped.append(pid)
            continue
        mass = (number(m.get("surcharge_mass_g")) or D(0)) / 1000
        index = _index_rate(indices.get(norm_id(m.get("price_index_key"))), T) if m.get("price_index_key") else None
        if m.get("price_index_key") and index is None:
            note(f"{pid}: metal index {m.get('price_index_key')} not found")
        mass_surcharge = mass * (index or D(0))
        group = latest("condition_group", pid)
        scope = clauses.get(norm_id(group.get("group")), "base_only") if group else "base_only"
        setup_fact = latest("setup_cost", pid)
        setup = (number(setup_fact.get("amount_eur")) or D(0)) if setup_fact else D(0)
        setup += pool_share.get(pid, D(0))
        a = assignments[pid]
        tariff = number((tariffs.get(norm_id(a.get("packaging_key"))) or {}).get("eur_per_carton")) if a.get("packaging_key") else None
        carton = integer(m.get("pieces_per_carton"))
        packaging = D(ceil(q / carton)) * tariff if tariff is not None and carton else D(0)
        bonus = bonus_share.get(pid, D(0))
        disc_base = base * (1 - d) if scope in ("base_only", "base_and_surcharge") else base
        disc_mass = mass_surcharge * (1 - d) if scope == "base_and_surcharge" else mass_surcharge
        unit_price = r2(disc_base + disc_mass + (setup + packaging - bonus) / q)
        lead = _lead_time(m, pooled[norm_id(m["material_number"])], commitments.get(norm_id(a.get("delivery_key"))) if a.get("delivery_key") else None)
        total += q * unit_price
        out_positions.append({
            "position": pid, "material_number": m["material_number"], "quantity": q,
            "unit_price": float(unit_price), "lead_time_weeks": lead,
            "base_unit_price": float(base), "surcharge_per_unit": float(r2(mass_surcharge + setup / q)),
            "packaging_per_unit": float(r2(packaging / q)), "rebate_total": float(r2(bonus)),
        })
        breakdown[pid] = {"scope": scope, "index": index, "mass_surcharge": mass_surcharge, "setup": setup,
                          "packaging": packaging, "bonus": bonus, "unit_price": unit_price,
                          "filters": {k: m.get(k) for k in ("bore_mm", "stroke_mm", "pressure_bar", "mounting", "certification")}}
        note(f"{pid}: {m['material_number']} q={q} base={base} scope={scope} mass={mass_surcharge} setup={setup} "
             f"pack={packaging} bonus={bonus} -> {unit_price}, lead {lead}")
    answer = {"tender_reference": ctx.tender_reference, "decision": "bid", "currency": "EUR",
              "discount_percent": float(discount), "positions": out_positions, "total_net": float(r2(total))}
    return Result(answer, trace, sorted(set(skipped)), breakdown)


def _index_rate(entries, T: datetime) -> D | None:
    if not entries:
        return None
    if isinstance(entries, dict):
        entries = [entries]
    for e in entries:
        start, end = day(e.get("valid_from")), day(e.get("valid_to"))
        if (start is None or start <= T.date()) and (end is None or T.date() <= end):
            if start or end:
                return number(e.get("eur_per_kg"))
    return number(entries[-1].get("eur_per_kg"))


def _lead_time(m: dict, pooled_qty: int, commitment: dict | None) -> int:
    if commitment and norm_id(commitment.get("material")) == norm_id(m["material_number"]):
        limit = number(commitment.get("max_total_qty"))
        if limit is not None and pooled_qty <= limit:
            return integer(commitment.get("weeks")) or 0
    stock = number(m.get("unrestricted_stock"))
    if stock is not None and pooled_qty <= stock:
        return integer(m.get("lead_time_stock_weeks")) or 0
    return integer(m.get("lead_time_production_weeks")) or integer(m.get("lead_time_stock_weeks")) or 0

